import{_ as c,C as t,o as m,c as g,E as e,a0 as d}from"./chunks/framework.CQlhmJfM.js";const b=JSON.parse('{"title":"OTools 高性能AI工作流平台-小身躯大能量","titleTemplate":false,"description":"以 Tabs 多任务化为核心，统一插件生态、原生能力与桌面运行时。让每个工具都成为可组合的开放AI工作流模块。","frontmatter":{"layout":"page","aside":false,"head":[["meta",{"name":"keywords","content":"OTools,AI 工作流平台,桌面工具平台,插件生态,Tabs 多任务,开发者工具集合,独立版桌面工具"}],["meta",{"name":"author","content":"OTools"}],["link",{"rel":"canonical","href":"https://ootools.github.io/otools-website/"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"OTools"}],["meta",{"property":"og:title","content":"OTools 高性能AI工作流平台-小身躯大能量"}],["meta",{"property":"og:description","content":"以 Tabs 多任务化为核心，统一插件生态、原生能力与桌面运行时。让每个工具都成为可组合的开放AI工作流模块。"}],["meta",{"property":"og:url","content":"https://ootools.github.io/otools-website/"}],["meta",{"property":"og:image","content":"https://ootools.github.io/otools-website/otools-logo.svg"}],["meta",{"property":"og:image:width","content":"2880"}],["meta",{"property":"og:image:height","content":"1800"}],["meta",{"property":"og:locale","content":"zh_CN"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"OTools 高性能AI工作流平台-小身躯大能量"}],["meta",{"name":"twitter:description","content":"以 Tabs 多任务化为核心，统一插件生态、原生能力与桌面运行时。让每个工具都成为可组合的开放AI工作流模块。"}],["meta",{"name":"twitter:image","content":"https://ootools.github.io/otools-website/otools-logo.svg"}],["link",{"rel":"alternate","type":"text/plain","href":"/otools-website/llms.txt","title":"OTools 站点说明（AI 检索）"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"FAQPage\\",\\"mainEntity\\":[{\\"@type\\":\\"Question\\",\\"name\\":\\"OTools 是什么？可以免费用吗？\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"OTools 是一个把常用桌面工具收进同一个工作台的高性能 AI 工作流平台，核心是「Tabs 多任务化」：多个工具并行打开、保持上下文、随时切换。平台与内置插件均可免费下载，Windows 与macOS 行为一致。\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"每个工具有独立版吗？不想装整个平台行不行？\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"可以。Git、DBM、Term、MQTT、FTP、Env、Android Mirror 每个工具都有独立版，可脱离平台单独下载运行，功能不阉割。适合只想要其中一个工具、或想在多台机器上轻量部署的场景。\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"OTools 的 Git 客户端和 SourceTree / GitKraken 有什么区别？\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"OTools 是原生桌面实现，不依赖 Java/JRE，启动即用；同时把仓库列表、提交历史、文件树、Diff、终端放在同一屏，能完成「看改动 → 写命令 → 看结果」的完整闭环，不必在多个窗口切换。它也有独立版，可以当纯 Git GUI 使用。\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"有没有能替代 phpstudy / xampp 的本地服务管理工具？\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"有，Env（原 ServRun）就是。它的差异在于不止「装环境」：安装与运行状态、监听端口、版本号集中在一张面板；Nginx 虚拟主机可视化编辑；PHP 多版本共存与切换；服务配置文件在线编辑并可一键回滚。而且是纯本地进程管理，不需要常驻容器运行时或面板服务，启动快、占用低。\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"MQTT 调试除了 MQTTX 还有什么选择？\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"OTools MQTT 打开会话即可看到消息流，订阅树与日志同屏；载荷支持纯文本 / JSON / Base64 / Hex / CBOR 多视图切换，JSON 自动格式化；历史消息可一键重发复现问题；支持 MQTT 3.1.1 与 5.0、TLS 与遗嘱消息。开源免费跨平台。\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"支持哪些操作系统？需要联网吗？\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Windows 与 macOS 都支持，界面与快捷键一致。工具本身离线可用，联网只用于下载与版本更新。\\"}}]}"],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"WebSite\\",\\"name\\":\\"OTools\\",\\"url\\":\\"https://ootools.github.io/otools-website/\\",\\"inLanguage\\":\\"zh-CN\\",\\"potentialAction\\":{\\"@type\\":\\"SearchAction\\",\\"target\\":\\"https://ootools.github.io/otools-website/search?q={search_term_string}\\",\\"query-input\\":\\"required name=search_term_string\\"}}"]]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),_={name:"index.md"};function h(y,o,T,u,w,x){const n=t("HeroIntro"),s=t("OriginStory"),a=t("PlatformHighlights"),i=t("PluginShowcase"),r=t("PluginGrid"),l=t("TabsWorkflow"),p=t("DocCta");return m(),g("div",null,[e(n),e(s),e(a),e(i),e(r),e(l),o[0]||(o[0]=d("",1)),e(p)])}const O=c